import sys

def main():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return

    n = int(input_data[0])
    count = {}

    idx = 1
    for _ in range(n):
        size = int(input_data[idx])
        side = input_data[idx + 1]
        idx += 2

        if size not in count:
            count[size] = {'D': 0, 'E': 0}
        count[size][side] += 1

    pairs = 0
    for size in count:
        pairs += min(count[size]['D'], count[size]['E'])

    print(pairs)

if __name__ == "__main__":
    main()
